// 1. Sanitizar dados do cliente recebidos do portal web
const body = $input.first().json.body || $input.first().json;

const rawName = body.clientName || 'Novo Cliente';
const cleanSlug = 'coach-' + rawName
  .toLowerCase()
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .replace(/[^a-z0-9]/g, '-')
  .replace(/-+/g, '-')
  .substring(0, 20);

return {
  // ⚙️ DEFINA AS CONFIGURAÇÕES DA SUA EVOLUTION API AQUI:
  evolutionApiUrl: 'http://SEU_IP_PUBLICO:8080', // Ex: https://evolution.pedromarcio.site ou http://evolution-api:8080
  evolutionApiKey: 'SEU_EVOLUTION_APIKEY',       // Sua chave GLOBAL da Evolution API

  clientSlug: cleanSlug,
  clientName: rawName,
  clientPhone: body.clientPhone || '',
  calendarLink: body.calendarLink || '',
  niche: body.niche || '',
  createdAt: new Date().toISOString()
};

const body = $input.first().json.body || $input.first().json;
const userMsg = (body.userMessage || '').toLowerCase();
const isEn = (body.lang || 'pt') === 'en';
const mentorName = body.clientName || 'Assessor Executivo';
const calendar = body.calendarLink || 'https://calendar.google.com';

let botReply = '';
let isVip = false;

if (userMsg.includes('diretor') || userMsg.includes('vp') || userMsg.includes('28k') || userMsg.includes('urgente') || userMsg.includes('director') || userMsg.includes('240k') || userMsg.includes('urgent')) {
  isVip = true;
  botReply = isEn
    ? `[LIVE VPS AI] Outstanding track record. A leadership transition to VP demands board-level alignment, governance positioning, and ROI-anchored equity structuring.\n\nGiven your seniority, I have unlocked a private strategic session directly with ${mentorName}:\n👉 ${calendar}\n\n[VIP ALERT DISPATCHED: Real-time notification delivered to mentor's WhatsApp]`
    : `[IA REAL VPS] Excelente trajetória. Uma transição para cargos de Diretoria e VP exige calibração de governança e negociação de pacote de equity estratégico.\n\nPela relevância do seu perfil, reservei uma Sessão Estratégica Individual com ${mentorName}:\n👉 ${calendar}\n\n[ALERTA VIP DISPARADO: Notificação em tempo real enviada ao WhatsApp do mentor]`;
} else if (userMsg.includes('preço') || userMsg.includes('valor') || userMsg.includes('investimento') || userMsg.includes('price') || userMsg.includes('pricing') || userMsg.includes('cost')) {
  botReply = isEn
    ? `[LIVE VPS AI] Our acceleration programs are custom-calibrated to your current compensation tier and your 90-day trajectory. We work with 30-Day Executive Sprints up to ongoing Advisory partnerships.\n\nWhat is your target salary growth or executive role for this quarter?`
    : `[IA REAL VPS] A nossa aceleração é calibrada para o seu momento e meta nos próximos 90 dias. Trabalhamos com Sprints de 30 dias até Advisory contínuo.\n\nQual é o seu objetivo de aumento salarial ou novo cargo para este trimestre?`;
} else {
  botReply = isEn
    ? `[LIVE VPS AI] Our 90-day framework focuses on 3 pillars: 1) Executive Authority Repositioning, 2) Hidden Senior Job Market Access, and 3) Value-Based Compensation Package Negotiation.\n\nWhat is the single biggest bottleneck in your career right now?`
    : `[IA REAL VPS] A nossa metodologia de aceleração em 90 dias foca em 3 eixos: 1) Reposicionamento de Autoridade, 2) Mapeamento de Vagas Ocultas de Liderança e 3) Negociação com Base em ROI.\n\nQual é o principal obstáculo que você enfrenta na sua carreira hoje?`;
}

return {
  success: true,
  fromVps: true,
  instanceName: body.instanceName || 'coach-alex',
  reply: botReply,
  isVip,
  timestamp: new Date().toISOString()
};
